package org.ideaflow.nodes.update;
import java.io.*;import java.util.*;import org.ideaflow.api.*;import org.ideaflow.core.*;import org.ideaflow.knime.KnimeTableSupport;import org.ideaflow.knime.PopulationState;import org.ideaflow.knime.KnimeTableSupport.ProblemMetadata;import org.knime.core.data.*;import org.knime.core.data.def.DefaultRow;import org.knime.core.node.*;import org.knime.core.node.defaultnodesettings.SettingsModelIntegerBounded;import org.knime.core.node.defaultnodesettings.SettingsModelString;
public final class PopulationUpdateNodeModel extends NodeModel{
 static final String CFG_MODE="update_mode",CFG_REFERENCE_DIVISIONS="reference_divisions",CFG_SIZE_POLICY="population_size_policy",CFG_MINIMUM_SIZE="minimum_population_size";
 private final SettingsModelString mode=new SettingsModelString(CFG_MODE,"NSGA_II");private final SettingsModelIntegerBounded referenceDivisions=new SettingsModelIntegerBounded(CFG_REFERENCE_DIVISIONS,12,1,1000);private final SettingsModelString sizePolicy=new SettingsModelString(CFG_SIZE_POLICY,"FIXED");private final SettingsModelIntegerBounded minimumSize=new SettingsModelIntegerBounded(CFG_MINIMUM_SIZE,4,4,Integer.MAX_VALUE);
 PopulationUpdateNodeModel(){super(2,2);}@Override protected DataTableSpec[] configure(DataTableSpec[] in)throws InvalidSettingsException{validate(in);final DataTableSpec merged=mergedSpec(in[0],in[1]);return new DataTableSpec[]{merged,merged};}
 @Override protected BufferedDataTable[] execute(BufferedDataTable[] in,ExecutionContext exec)throws Exception{final DataTableSpec parentSpec=in[0].getDataTableSpec(),trialSpec=in[1].getDataTableSpec();validate(new DataTableSpec[]{parentSpec,trialSpec});final DataTableSpec spec=mergedSpec(parentSpec,trialSpec);final ProblemMetadata.Schema problem=ProblemMetadata.require(parentSpec);final List<String> names=problem.objectiveNames();final int[] obj=KnimeTableSupport.requireNumericColumns(spec,names);final List<OptimizationDirection> dirs=problem.objectives().stream().map(ProblemMetadata.Objective::direction).toList();final List<ObjectiveDefinition> defs=KnimeTableSupport.objectives(names,dirs,List.of());final int vio=spec.findColumnIndex(PopulationState.CONSTRAINT_VIOLATION);final Map<String,List<DataRow>> parents=groups(in[0],spec),trials=groups(in[1],spec);final BufferedDataContainer out=exec.createDataContainer(spec),discardedOut=exec.createDataContainer(spec);int rowNumber=0,discardedNumber=0;
  for(Map.Entry<String,List<DataRow>> entry:parents.entrySet()){final List<DataRow> p=entry.getValue(),t=trials.get(entry.getKey());if(t==null)throw new InvalidSettingsException("Missing trial population for group "+entry.getKey());final List<DataRow> considered=new ArrayList<>(),deArchiveRows=new ArrayList<>();considered.addAll(p);considered.addAll(t);final long groupNfe=maxNfe(considered,spec);final List<DataRow> pool=new ArrayList<>();if("GDE3".equals(mode.getStringValue())){if(p.size()!=t.size())throw new InvalidSettingsException("GDE3 requires one trial per parent.");for(int i=0;i<p.size();i++){final Candidate pc=candidate(p.get(i),obj,vio,names),tc=candidate(t.get(i),obj,vio,names);final int comparison=ParetoDominance.compare(pc,tc,defs);if(comparison<=0)pool.add(p.get(i));if(comparison>=0)pool.add(t.get(i));}}else if("DE_PAIRWISE".equals(mode.getStringValue())){if(p.size()!=t.size())throw new InvalidSettingsException("Pairwise DE update requires one trial per parent.");for(int i=0;i<p.size();i++){final Candidate pc=candidate(p.get(i),obj,vio,names),tc=candidate(t.get(i),obj,vio,names);final int constraint=Double.compare(pc.constraintViolation(),tc.constraintViolation());final boolean trialWins=pc.constraintViolation()>0||tc.constraintViolation()>0?constraint>0:defs.get(0).direction().normalize(tc.objectives()[0])<=defs.get(0).direction().normalize(pc.objectives()[0]);pool.add(trialWins?t.get(i):p.get(i));if(trialWins)deArchiveRows.add(p.get(i));}}else{pool.addAll(considered);}final int target=targetSize(p,spec,groupNfe,problem);final List<DataRow> selected=select(pool,target,obj,vio,names,defs);final Set<DataRow> selectedIdentity=Collections.newSetFromMap(new IdentityHashMap<>());selectedIdentity.addAll(selected);for(DataRow row:selected){out.addRowToTable(withNfe("Survivor"+(rowNumber++),row,spec,groupNfe));exec.checkCanceled();}final List<DataRow> discarded="DE_PAIRWISE".equals(mode.getStringValue())?deArchiveRows:considered;for(DataRow row:discarded)if("DE_PAIRWISE".equals(mode.getStringValue())||!selectedIdentity.contains(row))discardedOut.addRowToTable(withNfe("Discarded"+(discardedNumber++),row,spec,groupNfe));}
  out.close();discardedOut.close();return new BufferedDataTable[]{out.getTable(),discardedOut.getTable()};}
 private List<DataRow> select(List<DataRow> rows,int target,int[] obj,int vio,List<String> names,List<ObjectiveDefinition> defs)throws InvalidSettingsException{final List<Candidate> candidates=new ArrayList<>();for(DataRow row:rows)candidates.add(candidate(row,obj,vio,names));if("SINGLE_OBJECTIVE".equals(mode.getStringValue())){final List<Integer> order=new ArrayList<>();for(int i=0;i<rows.size();i++)order.add(i);order.sort((a,b)->{final int constraint=Double.compare(candidates.get(a).constraintViolation(),candidates.get(b).constraintViolation());if(candidates.get(a).constraintViolation()>0||candidates.get(b).constraintViolation()>0)return constraint;return Double.compare(defs.get(0).direction().normalize(candidates.get(a).objectives()[0]),defs.get(0).direction().normalize(candidates.get(b).objectives()[0]));});return order.stream().limit(target).map(rows::get).toList();}if("NSGA_III".equals(mode.getStringValue()))return Nsga3Selection.select(candidates,defs,target,referenceDivisions.getIntValue()).stream().map(rows::get).toList();final List<List<Integer>> fronts=FastNonDominatedSort.sort(candidates,defs);final double[] crowd=CrowdingDistance.compute(candidates,fronts,defs);final List<Integer> selected=new ArrayList<>();for(List<Integer> front:fronts){if(selected.size()+front.size()<=target)selected.addAll(front);else{final List<Integer> ordered=new ArrayList<>(front);ordered.sort(Comparator.<Integer>comparingDouble(i->crowd[i]).reversed().thenComparing(i->candidates.get(i).id()));selected.addAll(ordered.subList(0,target-selected.size()));break;}}return selected.stream().map(rows::get).toList();}
 private Candidate candidate(DataRow row,int[] obj,int vio,List<String> names)throws InvalidSettingsException{return KnimeTableSupport.candidate(row,new int[0],obj,vio,List.of(),names);}
 private int targetSize(List<DataRow> parents,DataTableSpec spec,long nfe,ProblemMetadata.Schema problem)throws InvalidSettingsException{if("FIXED".equals(sizePolicy.getStringValue()))return parents.size();int initial=parents.size();for(DataRow row:parents)initial=PopulationState.get(row,spec).intValue(IdeaFlowState.INITIAL_POPULATION_SIZE,initial);if(minimumSize.getIntValue()>initial)throw new InvalidSettingsException("Final population size cannot exceed the initial population size ("+initial+").");return Math.min(parents.size(),LinearPopulationSchedule.sizeAt(initial,minimumSize.getIntValue(),nfe,problem.maxEvaluations()));}
 private static long maxNfe(List<DataRow> rows,DataTableSpec spec){long maximum=0;for(DataRow row:rows)maximum=Math.max(maximum,PopulationState.nfe(row,spec));return maximum;}
 private static DataRow withNfe(String key,DataRow row,DataTableSpec spec,long nfe){final DataCell[] cells=new DataCell[spec.getNumColumns()];for(int i=0;i<cells.length;i++)cells[i]=row.getCell(i);PopulationState.setNfe(cells,spec,nfe);return new DefaultRow(key,cells);}
 private static Map<String,List<DataRow>> groups(BufferedDataTable table,DataTableSpec outputSpec)throws InvalidSettingsException{final Map<String,List<DataRow>> result=new LinkedHashMap<>();for(DataRow row:table){final DataRow normalized=new DefaultRow(row.getKey(),KnimeTableSupport.copyToSpec(row,table.getDataTableSpec(),outputSpec));result.computeIfAbsent(PopulationState.groupKey(normalized,outputSpec),k->new ArrayList<>()).add(normalized);}return result;}
 private static DataTableSpec mergedSpec(DataTableSpec parent,DataTableSpec trial)throws InvalidSettingsException{final List<DataColumnSpec> columns=new ArrayList<>();for(DataColumnSpec column:parent)columns.add(column);for(DataColumnSpec column:trial){final int existing=parent.findColumnIndex(column.getName());if(existing>=0){if(!parent.getColumnSpec(existing).getType().equals(column.getType()))throw new InvalidSettingsException("Parent and child column types differ: "+column.getName());}else columns.add(column);}return new DataTableSpec(parent.getName(),columns.toArray(DataColumnSpec[]::new));}
 private void validate(DataTableSpec[] specs)throws InvalidSettingsException{if(!List.of("FIXED","LINEAR_NFE").contains(sizePolicy.getStringValue()))throw new InvalidSettingsException("Unsupported population size policy: "+sizePolicy.getStringValue());for(String allowed:List.of("SINGLE_OBJECTIVE","DE_PAIRWISE","NSGA_II","NSGA_III","GDE3"))if(allowed.equals(mode.getStringValue())){final DataTableSpec parent=specs[0],trial=specs[1],merged=mergedSpec(parent,trial);final ProblemMetadata.Schema problem=ProblemMetadata.require(parent);final List<String> names=problem.objectiveNames();KnimeTableSupport.requireNumericColumns(parent,names);KnimeTableSupport.requireNumericColumns(trial,names);PopulationState.requireVisibleColumns(merged);if(("SINGLE_OBJECTIVE".equals(mode.getStringValue())||"DE_PAIRWISE".equals(mode.getStringValue()))&&names.size()!=1)throw new InvalidSettingsException("The selected update requires one objective.");if("NSGA_III".equals(mode.getStringValue())&&names.size()<3)throw new InvalidSettingsException("NSGA-III requires at least three objectives.");if(merged.findColumnIndex(PopulationState.CONSTRAINT_VIOLATION)>=0)KnimeTableSupport.requireNumericColumns(merged,List.of(PopulationState.CONSTRAINT_VIOLATION));return;}throw new InvalidSettingsException("Unsupported update mode: "+mode.getStringValue());}
 @Override protected void saveSettingsTo(NodeSettingsWO s){mode.saveSettingsTo(s);referenceDivisions.saveSettingsTo(s);sizePolicy.saveSettingsTo(s);minimumSize.saveSettingsTo(s);}@Override protected void validateSettings(NodeSettingsRO s)throws InvalidSettingsException{mode.validateSettings(s);referenceDivisions.validateSettings(s);if(s.containsKey(CFG_SIZE_POLICY))sizePolicy.validateSettings(s);if(s.containsKey(CFG_MINIMUM_SIZE))minimumSize.validateSettings(s);}@Override protected void loadValidatedSettingsFrom(NodeSettingsRO s)throws InvalidSettingsException{mode.loadSettingsFrom(s);referenceDivisions.loadSettingsFrom(s);if(s.containsKey(CFG_SIZE_POLICY))sizePolicy.loadSettingsFrom(s);if(s.containsKey(CFG_MINIMUM_SIZE))minimumSize.loadSettingsFrom(s);}@Override protected void loadInternals(File f,ExecutionMonitor e)throws IOException,CanceledExecutionException{}@Override protected void saveInternals(File f,ExecutionMonitor e)throws IOException,CanceledExecutionException{}@Override protected void reset(){}
}
